/** File name of a request: `/competition/2999/RCH/stats/scorers?limit=20` → `competition_2999_RCH_stats_scorers_limit=20.json`. */
export function fixtureFile(path) {
  return `${path.replace(/^\//, '').replace(/[/?&%]/g, '_')}.json`
}
